const BASE = process.env.SYGECOM_BASE_URL ?? "https://api.sagierp.com.br/api/v1";
const EMAIL = process.env.SYGECOM_EMAIL!;   // <<USUARIO_EMAIL>>
const SENHA = process.env.SYGECOM_SENHA!;   // <<SENHA>>

async function login(): Promise<string> {
  const r = await fetch(`${BASE}/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: EMAIL, password: SENHA, origem: "API" }),
  });
  if (r.status === 403) throw new Error(`bloqueio de acesso: ${await r.text()}`);
  if (!r.ok) throw new Error(`login falhou: HTTP ${r.status}`);
  const d: any = await r.json();
  return d.token ?? d.user[0].token;   // /login devolve na raiz, /auth dentro de user[0]
}

login().then((t) => console.log(`token obtido, ${t.length} caracteres`));

