             else if Status >= 400 then error "HTTP " & Text.From(Status)
             else let lote = Json.Document(Resposta) in lote,
    Tabela = if List.IsEmpty(Linhas) then #table({}, {}) else Table.FromRecords(Linhas)
in
    Tabela

